<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref} from 'vue';import {Head,Link,router} from '@inertiajs/vue3';import {Download,Trash2,BookOpen,RefreshCw,FileArchive} from 'lucide-vue-next';
interface Item{manga_id:string;chapter_id:string;manga_title:string|null;chapter_name:string|null;status:string;saved_pages:number;total_pages:number;error:string|null}
defineProps<{items:Item[]}>();const busy=ref(false);let interval:number|null=null;
onMounted(()=>{interval=window.setInterval(()=>{if(!document.hidden)router.reload({only:['items'],preserveScroll:true});},8000);});
onBeforeUnmount(()=>{if(interval!==null)clearInterval(interval);});
function remove(it:Item){if(!confirm('¿Eliminar esta descarga guardada en el servidor?'))return;busy.value=true;router.delete(`/downloads/${it.manga_id}/${it.chapter_id}`,{onFinish:()=>busy.value=false});}
</script>
<template><Head title="Descargas"/><div class="content"><div class="page-head"><div><div class="eyebrow">✦ Contenido guardado</div><h1>Descargas</h1><p class="lead">Guardá capítulos en el servidor, leelos aunque Suwayomi deje de estar disponible y exportalos en CBZ.</p></div><span class="pill"><Download :size="15"/> {{items.length}} capítulos</span></div>
<div class="notice">Las descargas se procesan en una cola. Además de MangaWeb, mantené abierta la terminal <strong>INICIAR_DESCARGAS.bat</strong> mientras se descargan los capítulos. Una vez completados, quedan guardados en el servidor de MangaWeb. No es descarga sin conexión al dispositivo.</div>
<div v-if="items.length" class="table-rows"><div v-for="it in items" :key="`${it.manga_id}-${it.chapter_id}`" class="history-item"><div class="badge-icon"><Download/></div><div style="flex:1;min-width:0"><div class="history-title">{{it.manga_title||`Manga ${it.manga_id}`}}</div><div class="history-sub">{{it.chapter_name||`Capítulo ${it.chapter_id}`}}</div><div class="page-controls"><span class="pill" :class="it.status==='ready'?'green':'gray'">{{it.status==='ready'?'Disponible':it.status==='running'?'Descargando':it.status==='queued'?'En cola':'Error'}}</span><span class="tiny">{{it.saved_pages}} / {{it.total_pages}} páginas</span></div><p v-if="it.error" class="error-text">{{it.error}}</p></div><div class="page-controls"><Link v-if="it.status==='ready'" :href="`/manga/${it.manga_id}/read/${it.chapter_id}`" class="button secondary"><BookOpen/> Leer</Link><a v-if="it.status==='ready'" :href="`/downloads/${it.manga_id}/${it.chapter_id}/cbz`" class="button secondary"><FileArchive/> CBZ</a><button v-if="it.status==='ready'||it.status==='error'" class="button danger" :disabled="busy" @click="remove(it)"><Trash2/> Eliminar</button></div></div></div>
<div v-else class="empty"><div class="empty-icon"><Download/></div><h3>Todavía no hay descargas</h3><p>Abrí los detalles de un manga y elegí «Descargar» en un capítulo.</p><Link href="/explore" class="button primary">Explorar mangas</Link></div>
<button class="button secondary" style="margin-top:18px" @click="router.reload({only:['items']})"><RefreshCw/> Actualizar estado</button></div></template>
